mapper.select:
SELECT 
FROM counter_summaries s JOIN users u ON u.id = s.user_id
WHERE s.id = #{id}

SELECT 
FROM counter_summaries s JOIN users u ON u.id = s.user_id
WHERE s.code = #{code}

SELECT s.id, s.code, s.ticket_no, u.name AS user_name, s.status, s.created_at, (SELECT COUNT(*) FROM summary_items i WHERE i.summary_id = s.id AND i.section <> 'PREP') AS item_count FROM counter_summaries s JOIN users u ON u.id = s.user_id
s.status = #{status}
ORDER BY s.created_at DESC, s.id DESC

SELECT 
FROM summary_items i
WHERE i.summary_id = #{summaryId} AND i.id = #{itemId}
